begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
-- All test identities are transaction-local fixtures, not production users.
insert into public.organizations(id,name,code,type) values ('a2000000-0000-4000-8000-000000000001','Organization 1','M12-ORG-1','OTHER');
insert into public.organizations(id,name,code,type) values ('a2000000-0000-4000-8000-000000000002','Organization 2','M12-ORG-2','OTHER');
insert into public.organizations(id,name,code,type) values ('a2000000-0000-4000-8000-000000000003','Organization 3','M12-ORG-3','OTHER');
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000001');
update public.profiles set account_status='ACTIVE',display_name='Fixture 1' where id='a1000000-0000-4000-8000-000000000001';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000002');
update public.profiles set account_status='ACTIVE',display_name='Fixture 2' where id='a1000000-0000-4000-8000-000000000002';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000003');
update public.profiles set account_status='ACTIVE',display_name='Fixture 3' where id='a1000000-0000-4000-8000-000000000003';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000004');
update public.profiles set account_status='ACTIVE',display_name='Fixture 4' where id='a1000000-0000-4000-8000-000000000004';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000005');
update public.profiles set account_status='PENDING_APPROVAL',display_name='Fixture 5' where id='a1000000-0000-4000-8000-000000000005';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000006');
update public.profiles set account_status='SUSPENDED',display_name='Fixture 6' where id='a1000000-0000-4000-8000-000000000006';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000007');
update public.profiles set account_status='REJECTED',display_name='Fixture 7' where id='a1000000-0000-4000-8000-000000000007';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000008');
update public.profiles set account_status='ACTIVE',display_name='Fixture 8' where id='a1000000-0000-4000-8000-000000000008';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000009');
update public.profiles set account_status='ACTIVE',display_name='Fixture 9' where id='a1000000-0000-4000-8000-000000000009';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000010');
-- Deliberately corrupt fixture to retain missing-profile fail-closed coverage.
delete from public.profiles where id='a1000000-0000-4000-8000-000000000010';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000011');
update public.profiles set account_status='ACTIVE',display_name='Fixture 11' where id='a1000000-0000-4000-8000-000000000011';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000012');
update public.profiles set account_status='ACTIVE',display_name='Fixture 12' where id='a1000000-0000-4000-8000-000000000012';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000013');
update public.profiles set account_status='ACTIVE',display_name='Fixture 13' where id='a1000000-0000-4000-8000-000000000013';
insert into auth.users(id) values ('a1000000-0000-4000-8000-000000000014');
update public.profiles set account_status='ACTIVE',display_name='Fixture 14' where id='a1000000-0000-4000-8000-000000000014';
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','FIREFIGHTER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000002','a2000000-0000-4000-8000-000000000002','FIREFIGHTER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000003','a2000000-0000-4000-8000-000000000001','MANAGER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000004','a2000000-0000-4000-8000-000000000001','ADMIN');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000005','a2000000-0000-4000-8000-000000000001','FIREFIGHTER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000006','a2000000-0000-4000-8000-000000000001','ADMIN');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000007','a2000000-0000-4000-8000-000000000001','MANAGER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000009','a2000000-0000-4000-8000-000000000001','FIREFIGHTER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000009','a2000000-0000-4000-8000-000000000002','MANAGER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000011','a2000000-0000-4000-8000-000000000001','MANAGER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000013','a2000000-0000-4000-8000-000000000001','FIREFIGHTER');
insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000014','a2000000-0000-4000-8000-000000000002','ADMIN');

-- Schema, ACL and helper hardening.
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '23505', null, 'duplicate membership is rejected');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','OWNER')$test$, '23514', null, 'invalid application role is rejected');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001',null)$test$, '23502', null, 'membership role is mandatory');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000010','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '23503', null, 'membership must reference an application profile');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000099','FIREFIGHTER')$test$, '23503', null, 'membership must reference an organization');
select ok((select created_at is not null from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001'), 'membership creation time generated by database');
select ok((select relrowsecurity from pg_class where oid='public.user_organizations'::regclass), 'membership RLS enabled');
select ok((select not has_schema_privilege('authenticated','private','CREATE')), 'clients cannot replace private helpers');
select ok((select not has_schema_privilege('anon','private','USAGE')), 'anonymous cannot use private schema');
select ok((select not has_function_privilege('anon','private.is_active_user()','EXECUTE')), 'private.is_active_user() not executable anonymously');
select ok((select has_function_privilege('authenticated','private.is_active_user()','EXECUTE')), 'private.is_active_user() executable for policies');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='private.is_active_user()'::regprocedure), 'private.is_active_user() has fixed empty search_path');
select ok((select not has_function_privilege('anon','private.has_organization_role(uuid,text[])','EXECUTE')), 'private.has_organization_role(uuid,text[]) not executable anonymously');
select ok((select has_function_privilege('authenticated','private.has_organization_role(uuid,text[])','EXECUTE')), 'private.has_organization_role(uuid,text[]) executable for policies');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='private.has_organization_role(uuid,text[])'::regprocedure), 'private.has_organization_role(uuid,text[]) has fixed empty search_path');
select ok((select not has_function_privilege('anon','private.is_organization_member(uuid)','EXECUTE')), 'private.is_organization_member(uuid) not executable anonymously');
select ok((select has_function_privilege('authenticated','private.is_organization_member(uuid)','EXECUTE')), 'private.is_organization_member(uuid) executable for policies');
select ok((select proconfig @> array['search_path=""'] from pg_proc where oid='private.is_organization_member(uuid)'::regprocedure), 'private.is_organization_member(uuid) has fixed empty search_path');
select ok((select not prosecdef from pg_proc where oid='private.is_organization_member(uuid)'::regprocedure), 'member wrapper does not need definer security');

-- Anonymous direct database/API role.
set local request.jwt.claims='{}';
set local role anon;
select throws_ok($test$select * from public.countries$test$, '42501', null, 'anonymous SELECT denied: countries');
select throws_ok($test$delete from public.countries$test$, '42501', null, 'anonymous DELETE denied: countries');
select throws_ok($test$select * from public.administrative_areas$test$, '42501', null, 'anonymous SELECT denied: administrative_areas');
select throws_ok($test$delete from public.administrative_areas$test$, '42501', null, 'anonymous DELETE denied: administrative_areas');
select throws_ok($test$select * from public.profiles$test$, '42501', null, 'anonymous SELECT denied: profiles');
select throws_ok($test$delete from public.profiles$test$, '42501', null, 'anonymous DELETE denied: profiles');
select throws_ok($test$select * from public.organizations$test$, '42501', null, 'anonymous SELECT denied: organizations');
select throws_ok($test$delete from public.organizations$test$, '42501', null, 'anonymous DELETE denied: organizations');
select throws_ok($test$select * from public.user_organizations$test$, '42501', null, 'anonymous SELECT denied: user_organizations');
select throws_ok($test$delete from public.user_organizations$test$, '42501', null, 'anonymous DELETE denied: user_organizations');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'anonymous membership insert denied');
select throws_ok($test$update public.user_organizations set role='ADMIN'$test$, '42501', null, 'anonymous membership update denied');
select throws_ok($test$select private.is_active_user()$test$, '42501', null, 'anonymous helper invocation denied');
reset role;
set local role authenticated;
select ok((select not private.is_active_user()), 'missing JWT identity is not active');
select ok((select not private.is_organization_member('a2000000-0000-4000-8000-000000000001')), 'missing JWT identity has no membership');
select is((select count(*) from public.countries)::integer, 0, 'authenticated database role without JWT identity has no geography');

-- ACTIVE firefighter A: own profile/preferences, own organization and membership.
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated"}';
set local role authenticated;
select ok((select private.is_active_user()), 'ACTIVE helper returns true');
select ok((select private.is_organization_member('a2000000-0000-4000-8000-000000000001')), 'member helper permits own organization');
select ok((select not private.is_organization_member('a2000000-0000-4000-8000-000000000002')), 'member helper denies other organization');
select ok((select private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['FIREFIGHTER'])), 'stored firefighter role recognized');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['ADMIN','MANAGER'])), 'role helper does not elevate firefighter');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',null)), 'null role list denies');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array[]::text[])), 'empty role list denies');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['OWNER',null])), 'unknown/null roles deny');
select ok((select not private.is_organization_member(null)), 'null organization denies');
select is((select count(*) from public.profiles)::integer, 1, 'own profile only');
select is((select count(*) from public.profiles where id='a1000000-0000-4000-8000-000000000002')::integer, 0, 'cross-user profile hidden');
select is((select count(*) from public.organizations where id='a2000000-0000-4000-8000-000000000001')::integer, 1, 'A reads Org A');
select is((select count(*) from public.organizations where id='a2000000-0000-4000-8000-000000000002')::integer, 0, 'A cannot read Org B');
select is((select count(*) from public.user_organizations)::integer, 1, 'firefighter reads only own membership');
select is((select count(*) from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000003')::integer, 0, 'firefighter cannot inspect same-org peer membership');
select is((select count(*) from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000002')::integer, 0, 'firefighter cannot inspect other-org member');
with changed as (update public.profiles set display_name='Updated',preferred_language='de',start_screen='MAP',inspection_mode='QUICK' where id='a1000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'all four safe self preferences can update');
select ok((select display_name='Updated' and preferred_language='de' and start_screen='MAP' and inspection_mode='QUICK' from public.profiles where id='a1000000-0000-4000-8000-000000000001'), 'safe preference update persisted');
select throws_ok($test$update public.profiles set preferred_language='en' where id='a1000000-0000-4000-8000-000000000001'$test$, '23514', null, 'client preference update still enforces language constraint');
select throws_ok($test$update public.profiles set account_status='ACTIVE' where id='a1000000-0000-4000-8000-000000000001'$test$, '42501', null, 'client cannot update protected profile field account_status');
select throws_ok($test$update public.profiles set email='attacker@example.invalid' where id='a1000000-0000-4000-8000-000000000001'$test$, '42501', null, 'client cannot update protected profile field email');
select throws_ok($test$update public.profiles set id='a1000000-0000-4000-8000-000000000002' where id='a1000000-0000-4000-8000-000000000001'$test$, '42501', null, 'client cannot update protected profile field id');
select throws_ok($test$update public.profiles set created_at='2000-01-01' where id='a1000000-0000-4000-8000-000000000001'$test$, '42501', null, 'client cannot update protected profile field created_at');
select throws_ok($test$update public.profiles set updated_at='2100-01-01' where id='a1000000-0000-4000-8000-000000000001'$test$, '42501', null, 'client cannot update protected profile field updated_at');
with changed as (update public.profiles set display_name='Intrusion' where id='a1000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 0, 'cross-user safe-field update affects no rows');
select throws_ok($test$insert into public.profiles(id,account_status) values ('a1000000-0000-4000-8000-000000000010','ACTIVE')$test$, '42501', null, 'client cannot create an ACTIVE profile');
select throws_ok($test$delete from public.profiles where id='a1000000-0000-4000-8000-000000000001'$test$, '42501', null, 'client cannot delete own profile');
select throws_ok($test$update public.organizations set name='Intrusion' where id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'firefighter organization mutation denied');
select throws_ok($test$delete from public.organizations where id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'firefighter organization mutation denied');
select throws_ok($test$insert into public.organizations(name,code,type) values ('Intrusion','INTRUSION','OTHER')$test$, '42501', null, 'firefighter organization mutation denied');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'firefighter cannot promote self');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000003' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'firefighter cannot change another membership');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'firefighter cannot delete own membership');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000002' and organization_id='a2000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 0, 'firefighter cannot delete another organization membership');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'firefighter cannot add users');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000002','FIREFIGHTER')$test$, '42501', null, 'firefighter cannot join Org B directly');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000001','a2000000-0000-4000-8000-000000000001','ADMIN') on conflict (user_id,organization_id) do update set role=excluded.role$test$, '42501', null, 'firefighter UPSERT self-promotion blocked');
select throws_ok($test$update public.user_organizations set user_id='a1000000-0000-4000-8000-000000000012' where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'membership identity/time immutable: user_id');
select throws_ok($test$update public.user_organizations set organization_id='a2000000-0000-4000-8000-000000000002' where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'membership identity/time immutable: organization_id');
select throws_ok($test$update public.user_organizations set created_at='2100-01-01' where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'membership identity/time immutable: created_at');

-- Reverse isolation, unaffiliated identity, no-profile identity and geography.
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000002","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.organizations where id='a2000000-0000-4000-8000-000000000002')::integer, 1, 'B reads Org B');
select is((select count(*) from public.organizations where id='a2000000-0000-4000-8000-000000000001')::integer, 0, 'B cannot read Org A');
select is((select count(*) from public.user_organizations where organization_id='a2000000-0000-4000-8000-000000000001')::integer, 0, 'B cannot enumerate A memberships');
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000008","role":"authenticated"}';
set local role authenticated;
select ok((select count(*)>0 from public.countries), 'unaffiliated identity 8 can read countries');
select ok((select count(*)>0 from public.administrative_areas), 'unaffiliated identity 8 can read areas');
select is((select count(*) from public.organizations)::integer, 0, 'unaffiliated identity 8 cannot enumerate organizations');
select is((select count(*) from public.user_organizations)::integer, 0, 'unaffiliated identity 8 has no memberships');
select is((select count(*) from public.profiles)::integer, 1, 'unaffiliated own profile behavior 8');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000008','a2000000-0000-4000-8000-000000000001','ADMIN')$test$, '42501', null, 'unaffiliated self-join denied 8');
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000010","role":"authenticated"}';
set local role authenticated;
select ok((select count(*)>0 from public.countries), 'unaffiliated identity 10 can read countries');
select ok((select count(*)>0 from public.administrative_areas), 'unaffiliated identity 10 can read areas');
select is((select count(*) from public.organizations)::integer, 0, 'unaffiliated identity 10 cannot enumerate organizations');
select is((select count(*) from public.user_organizations)::integer, 0, 'unaffiliated identity 10 has no memberships');
select is((select count(*) from public.profiles)::integer, 0, 'unaffiliated own profile behavior 10');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000010','a2000000-0000-4000-8000-000000000001','ADMIN')$test$, '42501', null, 'unaffiliated self-join denied 10');
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000008","role":"authenticated"}';
set local role authenticated;
select throws_ok($test$insert into public.countries(code,name) values ('XY','Intrusion')$test$, '42501', null, 'client geography INSERT denied countries');
select throws_ok($test$update public.countries set active=false$test$, '42501', null, 'client geography UPDATE denied countries');
select throws_ok($test$delete from public.countries$test$, '42501', null, 'client geography DELETE denied countries');
select throws_ok($test$insert into public.administrative_areas(country_id,name,area_type) values ('10000000-0000-4000-8000-000000000001','Intrusion','REGION')$test$, '42501', null, 'client geography INSERT denied administrative_areas');
select throws_ok($test$update public.administrative_areas set active=false$test$, '42501', null, 'client geography UPDATE denied administrative_areas');
select throws_ok($test$delete from public.administrative_areas$test$, '42501', null, 'client geography DELETE denied administrative_areas');

-- MANAGER A: inspect roster, add/remove only FIREFIGHTER rows.
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.user_organizations where organization_id='a2000000-0000-4000-8000-000000000001')::integer, 9, 'manager reads complete own-org roster');
select is((select count(*) from public.user_organizations where organization_id='a2000000-0000-4000-8000-000000000002')::integer, 0, 'manager cannot read other-org roster');
select is((select count(*) from public.profiles where id='a1000000-0000-4000-8000-000000000001')::integer, 0, 'manager roster permission does not expose peer profile');
with changed as (insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER') returning *) select is((select count(*)::integer from changed), 1, 'manager can add firefighter');
with changed as (update public.user_organizations set role='FIREFIGHTER' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'manager permitted firefighter update');
select throws_ok($test$update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'manager cannot promote firefighter to ADMIN');
select throws_ok($test$update public.user_organizations set role='MANAGER' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'manager cannot promote firefighter to MANAGER');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000003' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot promote self');
with changed as (update public.user_organizations set role='FIREFIGHTER' where user_id='a1000000-0000-4000-8000-000000000004' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot modify an ADMIN');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000004' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot delete an ADMIN');
with changed as (update public.user_organizations set role='FIREFIGHTER' where user_id='a1000000-0000-4000-8000-000000000011' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot modify another MANAGER');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000011' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot remove another MANAGER');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'manager can remove firefighter');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','ADMIN')$test$, '42501', null, 'manager cannot create ADMIN');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','MANAGER')$test$, '42501', null, 'manager cannot create MANAGER');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000002','FIREFIGHTER')$test$, '42501', null, 'manager cannot add to another organization');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000002' and organization_id='a2000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot remove cross-org firefighter');
with changed as (update public.user_organizations set role='FIREFIGHTER' where user_id='a1000000-0000-4000-8000-000000000002' and organization_id='a2000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 0, 'manager cannot update cross-org firefighter');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000004','a2000000-0000-4000-8000-000000000001','FIREFIGHTER') on conflict (user_id,organization_id) do update set role=excluded.role$test$, '42501', null, 'manager UPSERT cannot overwrite ADMIN');
select throws_ok($test$update public.organizations set name='Intrusion' where id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'manager cannot mutate organization settings');

-- Multiple memberships: role is scoped to each organization.
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000009","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.organizations)::integer, 2, 'multi-org user reads both authorized organizations');
select ok((select private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['FIREFIGHTER']) and not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['MANAGER'])), 'multi-org A role remains firefighter');
select ok((select private.has_organization_role('a2000000-0000-4000-8000-000000000002',array['MANAGER'])), 'multi-org B role is manager');
select is((select count(*) from public.user_organizations where organization_id='a2000000-0000-4000-8000-000000000001')::integer, 1, 'multi-org firefighter sees only own A membership');
select is((select count(*) from public.user_organizations where organization_id='a2000000-0000-4000-8000-000000000002')::integer, 3, 'multi-org manager sees B roster');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'B manager authority cannot leak into A');
with changed as (insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000002','FIREFIGHTER') returning *) select is((select count(*)::integer from changed), 1, 'B manager can add B firefighter');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 1, 'B manager can remove B firefighter');

-- ADMIN A: all membership roles, but only inside A.
