with changed as (insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','MANAGER') returning *) select is((select count(*)::integer from changed), 1, 'admin can create MANAGER');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'admin can remove MANAGER');
