with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'admin can remove ADMIN');
with changed as (insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER') returning *) select is((select count(*)::integer from changed), 1, 'admin creates promotion target');
with changed as (update public.user_organizations set role='MANAGER' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'admin can change membership role to MANAGER');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'admin can change membership role to ADMIN');
with changed as (update public.user_organizations set role='FIREFIGHTER' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'admin can change membership role to FIREFIGHTER');
select throws_ok($test$update public.user_organizations set role='OWNER' where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '23514', null, 'even admin cannot store invalid role');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000012' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 1, 'admin removes target');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000002','ADMIN')$test$, '42501', null, 'admin cannot add outside own org');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000004','a2000000-0000-4000-8000-000000000002','ADMIN')$test$, '42501', null, 'admin cannot self-join another org');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000002' and organization_id='a2000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 0, 'admin cannot promote another-org user');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000014' and organization_id='a2000000-0000-4000-8000-000000000002' returning *) select is((select count(*)::integer from changed), 0, 'admin cannot delete another-org admin');
select throws_ok($test$update public.user_organizations set organization_id='a2000000-0000-4000-8000-000000000002' where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'admin cannot move membership identity between organizations');
select throws_ok($test$update public.user_organizations set user_id='a1000000-0000-4000-8000-000000000012' where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'admin cannot swap membership identity');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role,created_at) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER','2100-01-01')$test$, '42501', null, 'admin client cannot forge created_at');
select throws_ok($test$update public.profiles set account_status='ACTIVE' where id='a1000000-0000-4000-8000-000000000005'$test$, '42501', null, 'org ADMIN is not global account approver');
select throws_ok($test$update public.organizations set active=false where id='a2000000-0000-4000-8000-000000000001'$test$, '42501', null, 'organization mutations remain backend-only even for ADMIN');
select is((select count(*) from public.profiles where id='a1000000-0000-4000-8000-000000000001')::integer, 0, 'ADMIN cannot enumerate other profiles');
select throws_ok($test$truncate public.user_organizations$test$, '42501', null, 'ADMIN client has no TRUNCATE bypass');

-- Account-state gate applies even when the stored membership is ADMIN.
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000005","role":"authenticated","user_metadata":{"role":"ADMIN","account_status":"ACTIVE"}}';
set local role authenticated;
select ok((select not private.is_active_user()), 'PENDING_APPROVAL ignores forged active metadata');
select ok((select not private.is_organization_member('a2000000-0000-4000-8000-000000000001')), 'PENDING_APPROVAL membership is not effective access');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['FIREFIGHTER','MANAGER','ADMIN'])), 'PENDING_APPROVAL role helper denies all roles');
select is((select count(*) from public.profiles)::integer, 0, 'PENDING_APPROVAL cannot read profiles');
select is((select count(*) from public.organizations)::integer, 0, 'PENDING_APPROVAL cannot read organizations');
select is((select count(*) from public.user_organizations)::integer, 0, 'PENDING_APPROVAL cannot read user_organizations');
select ok((select count(*)>0 from public.countries), 'PENDING_APPROVAL may read non-secret geography');
select throws_ok($test$update public.profiles set account_status='ACTIVE' where id='a1000000-0000-4000-8000-000000000005'$test$, '42501', null, 'PENDING_APPROVAL cannot self-activate');
with changed as (update public.profiles set display_name='Intrusion' where id='a1000000-0000-4000-8000-000000000005' returning *) select is((select count(*)::integer from changed), 0, 'PENDING_APPROVAL cannot edit protected profile');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'PENDING_APPROVAL cannot insert memberships');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000005' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'PENDING_APPROVAL cannot update memberships');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'PENDING_APPROVAL cannot delete memberships');
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000006","role":"authenticated","user_metadata":{"role":"ADMIN","account_status":"ACTIVE"}}';
set local role authenticated;
select ok((select not private.is_active_user()), 'SUSPENDED ignores forged active metadata');
select ok((select not private.is_organization_member('a2000000-0000-4000-8000-000000000001')), 'SUSPENDED membership is not effective access');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['FIREFIGHTER','MANAGER','ADMIN'])), 'SUSPENDED role helper denies all roles');
select is((select count(*) from public.profiles)::integer, 0, 'SUSPENDED cannot read profiles');
select is((select count(*) from public.organizations)::integer, 0, 'SUSPENDED cannot read organizations');
select is((select count(*) from public.user_organizations)::integer, 0, 'SUSPENDED cannot read user_organizations');
select ok((select count(*)>0 from public.countries), 'SUSPENDED may read non-secret geography');
select throws_ok($test$update public.profiles set account_status='ACTIVE' where id='a1000000-0000-4000-8000-000000000006'$test$, '42501', null, 'SUSPENDED cannot self-activate');
with changed as (update public.profiles set display_name='Intrusion' where id='a1000000-0000-4000-8000-000000000006' returning *) select is((select count(*)::integer from changed), 0, 'SUSPENDED cannot edit protected profile');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'SUSPENDED cannot insert memberships');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000006' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'SUSPENDED cannot update memberships');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'SUSPENDED cannot delete memberships');
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000007","role":"authenticated","user_metadata":{"role":"ADMIN","account_status":"ACTIVE"}}';
set local role authenticated;
select ok((select not private.is_active_user()), 'REJECTED ignores forged active metadata');
select ok((select not private.is_organization_member('a2000000-0000-4000-8000-000000000001')), 'REJECTED membership is not effective access');
select ok((select not private.has_organization_role('a2000000-0000-4000-8000-000000000001',array['FIREFIGHTER','MANAGER','ADMIN'])), 'REJECTED role helper denies all roles');
select is((select count(*) from public.profiles)::integer, 0, 'REJECTED cannot read profiles');
