select throws_ok($test$update public.profiles set account_status='ACTIVE' where id='a1000000-0000-4000-8000-000000000007'$test$, '42501', null, 'REJECTED cannot self-activate');
with changed as (update public.profiles set display_name='Intrusion' where id='a1000000-0000-4000-8000-000000000007' returning *) select is((select count(*)::integer from changed), 0, 'REJECTED cannot edit protected profile');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'REJECTED cannot insert memberships');
with changed as (update public.user_organizations set role='ADMIN' where user_id='a1000000-0000-4000-8000-000000000007' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'REJECTED cannot update memberships');
with changed as (delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001' returning *) select is((select count(*)::integer from changed), 0, 'REJECTED cannot delete memberships');

-- Suspension and membership removal take effect on the next statement.
reset role;
update public.profiles set account_status='SUSPENDED' where id='a1000000-0000-4000-8000-000000000003';
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.organizations)::integer, 0, 'newly suspended manager immediately loses org reads');
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','FIREFIGHTER')$test$, '42501', null, 'newly suspended manager loses writes');
reset role;
update public.profiles set account_status='ACTIVE' where id='a1000000-0000-4000-8000-000000000003';
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000003","role":"authenticated"}';
set local role authenticated;
select is((select count(*) from public.organizations where id='a2000000-0000-4000-8000-000000000001')::integer, 1, 'reactivated membership access restored by backend');
reset role;
delete from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000001' and organization_id='a2000000-0000-4000-8000-000000000001';
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000001","role":"authenticated"}';
set local role authenticated;
select ok((select not private.is_organization_member('a2000000-0000-4000-8000-000000000001')), 'removed membership is not cached in JWT');
select is((select count(*) from public.organizations)::integer, 0, 'removed member loses org reads');
select is((select count(*) from public.profiles)::integer, 1, 'ACTIVE user retains own profile without membership');
reset role;
set local request.jwt.claims = '{"sub":"a1000000-0000-4000-8000-000000000003","role":"authenticated","user_metadata":{"role":"ADMIN"}}';
set local role authenticated;
select throws_ok($test$insert into public.user_organizations(user_id,organization_id,role) values ('a1000000-0000-4000-8000-000000000012','a2000000-0000-4000-8000-000000000001','ADMIN')$test$, '42501', null, 'forged metadata does not elevate active manager');
reset role;
select is((select count(*) from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000004' and organization_id='a2000000-0000-4000-8000-000000000001' and role='ADMIN')::integer, 1, 'attacks left real Org A ADMIN intact');
select is((select count(*) from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000014' and organization_id='a2000000-0000-4000-8000-000000000002' and role='ADMIN')::integer, 1, 'attacks left Org B ADMIN intact');
select is((select count(*) from public.user_organizations where user_id='a1000000-0000-4000-8000-000000000012')::integer, 0, 'temporary authorized additions removed and attacks persisted nothing');
select * from finish();
rollback;
